"""Source of truth for the Epstein network map. Writes network.json.
Node: id, name, kind (person|institution|company|government|place|document), cluster, tier, note, scenes, apex.
Edge: f, t, label, type, status (verified | to-verify | not-established), src.
'verified' = in a sourced simulation scene or checked live on the date in network.json; 'to-verify' = lead only."""
import json
N=[]; E=[]
def n(i,name,kind,cluster,note,tier='',scenes=(),apex=False): N.append(dict(id=i,name=name,kind=kind,cluster=cluster,tier=tier,note=note,scenes=list(scenes),apex=apex))
def e(f,t,label,typ,status,src): E.append(dict(f=f,t=t,label=label,type=typ,status=status,src=src))
V,T,X='verified','to-verify','not-established'

